import{_ as a,o as n,c as i,a as t}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"MySQL 日志系统完整学习笔记","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/relational/mysql/log.md","filePath":"data/database/relational/mysql/log.md"}'),l={name:"data/database/relational/mysql/log.md"};function e(o,s,d,_,r,h){return n(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="mysql-日志系统完整学习笔记" tabindex="-1">MySQL 日志系统完整学习笔记 <a class="header-anchor" href="#mysql-日志系统完整学习笔记" aria-label="Permalink to &quot;MySQL 日志系统完整学习笔记&quot;">​</a></h1><p>日志是 MySQL 体系中极其重要的组成部分。无论是故障诊断、性能调优、数据恢复还是主从复制，都离不开对各种日志的理解和运用。MySQL 的日志系统可以看作一系列分工明确的“黑匣子”，它们从不同维度记录着数据库的运行细节。</p><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-概述">概述</a></li><li><a href="#2-错误日志-error-log">错误日志 (Error Log)</a></li><li><a href="#3-通用查询日志-general-query-log">通用查询日志 (General Query Log)</a></li><li><a href="#4-慢查询日志-slow-query-log">慢查询日志 (Slow Query Log)</a></li><li><a href="#5-二进制日志-binary-log">二进制日志 (Binary Log)</a></li><li><a href="#6-中继日志-relay-log">中继日志 (Relay Log)</a></li><li><a href="#7-innodb-重做日志-redo-log">InnoDB 重做日志 (Redo Log)</a></li><li><a href="#8-innodb-撤销日志-undo-log">InnoDB 撤销日志 (Undo Log)</a></li><li><a href="#9-其他日志简介">其他日志简介</a></li><li><a href="#10-日志综合管理与最佳实践">日志综合管理与最佳实践</a></li><li><a href="#11-总结">总结</a></li></ol><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>MySQL 内置了多种日志，按层次可以划分为 <strong>Server 层日志</strong> 和 <strong>存储引擎层日志</strong>：</p><ul><li><strong>Server 层</strong>：错误日志、通用查询日志、慢查询日志、二进制日志、中继日志。</li><li><strong>InnoDB 层</strong>：重做日志 (Redo Log)、撤销日志 (Undo Log)。</li></ul><p>这些日志在<strong>故障恢复、数据复制、问题排查、性能分析、审计</strong>等场景中发挥着不可替代的作用。</p><hr><h2 id="_2-错误日志-error-log" tabindex="-1">2. 错误日志 (Error Log) <a class="header-anchor" href="#_2-错误日志-error-log" aria-label="Permalink to &quot;2. 错误日志 (Error Log)&quot;">​</a></h2><h3 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>记录 MySQL Server 启动、运行、关闭过程中的重要信息，尤其包含<strong>错误、警告和注解</strong>。当数据库出现故障时，错误日志是第一手诊断资料。</p><h3 id="日志内容" tabindex="-1">日志内容 <a class="header-anchor" href="#日志内容" aria-label="Permalink to &quot;日志内容&quot;">​</a></h3><ul><li>服务器启动/关闭时间</li><li>版本信息</li><li>严重错误（如表损坏、无法分配内存）</li><li>InnoDB 引擎的相关错误</li><li>复制过程中的 I/O 线程、SQL 线程错误</li><li>警告信息（例如，某些不推荐使用的语法）</li></ul><h3 id="配置参数" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>log_error</code></td><td>错误日志文件路径。若不配置，默认写到数据目录下的 <code>host_name.err</code></td></tr><tr><td><code>log_error_services</code> (8.0+)</td><td>日志服务组件链，如 <code>log_filter_internal; log_sink_internal</code></td></tr><tr><td><code>log_error_verbosity</code> (5.7+)</td><td>日志详细程度(1=仅错误,2=错误和警告,3=错误、警告和注释)</td></tr></tbody></table><h3 id="查看与管理" tabindex="-1">查看与管理 <a class="header-anchor" href="#查看与管理" aria-label="Permalink to &quot;查看与管理&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 查看错误日志位置</span></span>
<span class="line"><span class="__shiki_140thh">SHOW VARIABLES </span><span class="__shiki_1itgoe">LIKE</span><span class="__shiki_mdbnqw"> &#39;log_error&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 查看日志内容 (MySQL 8.0)</span></span>
<span class="line"><span class="__shiki_140thh">SHOW VARIABLES </span><span class="__shiki_1itgoe">LIKE</span><span class="__shiki_mdbnqw"> &#39;log_error_services&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 刷新错误日志（在操作系统层面重命名后，执行此命令新建日志文件）</span></span>
<span class="line"><span class="__shiki_140thh">FLUSH ERROR LOGS;</span></span></code></pre></div><h3 id="实用技巧" tabindex="-1">实用技巧 <a class="header-anchor" href="#实用技巧" aria-label="Permalink to &quot;实用技巧&quot;">​</a></h3><ul><li>当磁盘写满或表损坏时，错误日志通常会给出明确提示。</li><li>配合 <code>log_error_verbosity=3</code> 在开发环境可获取更多信息。</li><li>建议使用日志轮转工具（如 <code>logrotate</code>）定期归档，防止文件过大。</li></ul><hr><h2 id="_3-通用查询日志-general-query-log" tabindex="-1">3. 通用查询日志 (General Query Log) <a class="header-anchor" href="#_3-通用查询日志-general-query-log" aria-label="Permalink to &quot;3. 通用查询日志 (General Query Log)&quot;">​</a></h2><h3 id="作用-1" tabindex="-1">作用 <a class="header-anchor" href="#作用-1" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>记录所有客户端连接、断连和<strong>每一条执行的 SQL 语句</strong>。它是一个完整的“语句流水账”，在调试、审计时可能用到，但开启后会严重影响性能并迅速消耗磁盘空间，<strong>生产环境极少长期开启</strong>。</p><h3 id="配置参数-1" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数-1" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>general_log</code></td><td>是否开启 (ON/OFF)</td></tr><tr><td><code>general_log_file</code></td><td>日志文件路径，默认 <code>host_name.log</code></td></tr><tr><td><code>log_output</code></td><td>输出目标：<code>FILE</code>(文件)、<code>TABLE</code>(mysql.general_log 表)、<code>FILE,TABLE</code>(两者)</td></tr></tbody></table><h3 id="动态启用" tabindex="-1">动态启用 <a class="header-anchor" href="#动态启用" aria-label="Permalink to &quot;动态启用&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">SET</span><span class="__shiki_1itgoe"> GLOBAL</span><span class="__shiki_140thh"> general_log </span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw"> &#39;ON&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"><span class="__shiki_1itgoe">SET</span><span class="__shiki_1itgoe"> GLOBAL</span><span class="__shiki_140thh"> log_output </span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw"> &#39;FILE&#39;</span><span class="__shiki_140thh">;   </span><span class="__shiki_21nrsd">-- 或 &#39;TABLE&#39;</span></span></code></pre></div><h3 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to &quot;查看日志&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 文件类直接查看文件</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 表类查询</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_dzsirb"> mysql</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">general_log</span><span class="__shiki_1itgoe"> ORDER BY</span><span class="__shiki_140thh"> event_time </span><span class="__shiki_1itgoe">DESC</span><span class="__shiki_1itgoe"> LIMIT</span><span class="__shiki_dzsirb"> 20</span><span class="__shiki_140thh">;</span></span></code></pre></div><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>输出到表比文件开销更大，谨慎使用。</li><li>用完及时关闭：<code>SET GLOBAL general_log = &#39;OFF&#39;;</code>。</li><li>调试复杂问题时作为临时手段，不要作为持久审计方案。</li></ul><hr><h2 id="_4-慢查询日志-slow-query-log" tabindex="-1">4. 慢查询日志 (Slow Query Log) <a class="header-anchor" href="#_4-慢查询日志-slow-query-log" aria-label="Permalink to &quot;4. 慢查询日志 (Slow Query Log)&quot;">​</a></h2><h3 id="作用-2" tabindex="-1">作用 <a class="header-anchor" href="#作用-2" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>记录执行时间超过指定阈值的 SQL 语句，是<strong>性能优化</strong>中最重要的日志。</p><h3 id="配置参数-2" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数-2" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>slow_query_log</code></td><td>是否开启</td></tr><tr><td><code>slow_query_log_file</code></td><td>日志文件路径</td></tr><tr><td><code>long_query_time</code></td><td>阈值（秒），可精确到微秒</td></tr><tr><td><code>min_examined_row_limit</code></td><td>扫描行数少于该值的语句不记录</td></tr><tr><td><code>log_queries_not_using_indexes</code></td><td>是否记录未使用索引的查询</td></tr><tr><td><code>log_slow_admin_statements</code></td><td>是否记录慢管理语句（如 ALTER, OPTIMIZE）</td></tr><tr><td><code>log_throttle_queries_not_using_indexes</code></td><td>每分钟最多记录多少条无索引查询</td></tr></tbody></table><h3 id="示例配置" tabindex="-1">示例配置 <a class="header-anchor" href="#示例配置" aria-label="Permalink to &quot;示例配置&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">[mysqld]</span></span>
<span class="line"><span class="__shiki_1itgoe">slow_query_log</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">slow_query_log_file</span><span class="__shiki_140thh"> = /var/log/mysql/slow.log</span></span>
<span class="line"><span class="__shiki_1itgoe">long_query_time</span><span class="__shiki_140thh"> = 2</span></span>
<span class="line"><span class="__shiki_1itgoe">log_queries_not_using_indexes</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">min_examined_row_limit</span><span class="__shiki_140thh"> = 1000</span></span></code></pre></div><h3 id="分析工具" tabindex="-1">分析工具 <a class="header-anchor" href="#分析工具" aria-label="Permalink to &quot;分析工具&quot;">​</a></h3><ul><li><strong>mysqldumpslow</strong> (官方)<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">mysqldumpslow</span><span class="__shiki_dzsirb"> -s</span><span class="__shiki_mdbnqw"> c</span><span class="__shiki_dzsirb"> -t</span><span class="__shiki_dzsirb"> 10</span><span class="__shiki_mdbnqw"> /var/log/mysql/slow.log</span><span class="__shiki_21nrsd">   # 按次数排序前10</span></span></code></pre></div></li><li><strong>pt-query-digest</strong> (Percona Toolkit) – 功能强大，生成汇总报表。</li><li><strong>Explain 分析</strong>：找到具体语句后，使用 <code>EXPLAIN</code> 进一步优化。</li></ul><h3 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h3><ul><li>将 <code>long_query_time</code> 设得稍低（如 0.5 秒），先收集所有潜在慢查询，优化后再提升阈值。</li><li>记录未使用索引的查询有助于发现索引缺失，但可能产生大量日志，配合 <code>log_throttle_queries_not_using_indexes</code> 限流。</li></ul><hr><h2 id="_5-二进制日志-binary-log" tabindex="-1">5. 二进制日志 (Binary Log) <a class="header-anchor" href="#_5-二进制日志-binary-log" aria-label="Permalink to &quot;5. 二进制日志 (Binary Log)&quot;">​</a></h2><h3 id="作用-3" tabindex="-1">作用 <a class="header-anchor" href="#作用-3" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>二进制日志记录所有修改数据库数据的 <strong>逻辑操作</strong>（如 INSERT、UPDATE、DELETE 及可能产生数据变化的 DDL）。核心用途：</p><ul><li><strong>复制</strong>：主库上的二进制日志传递到从库，从库重放实现数据同步。</li><li><strong>基于时间点的恢复 (PITR)</strong>：恢复全量备份后，重放二进制日志到指定时刻。</li></ul><h3 id="日志格式" tabindex="-1">日志格式 <a class="header-anchor" href="#日志格式" aria-label="Permalink to &quot;日志格式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>格式</th><th>特点</th></tr></thead><tbody><tr><td><code>STATEMENT</code></td><td>记录 SQL 语句本身，体积小，但某些函数（如 <code>NOW()</code>）可能导致主从不一致</td></tr><tr><td><code>ROW</code> (推荐)</td><td>记录每一行数据的变化，最安全，但体积大</td></tr><tr><td><code>MIXED</code></td><td>默认使用 STATEMENT，特定情况自动切换为 ROW</td></tr></tbody></table><h3 id="配置参数-3" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数-3" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>log_bin</code></td><td>指定二进制日志文件基础名（不指定路径则放数据目录）</td></tr><tr><td><code>server_id</code></td><td>必须显式指定，每个服务器唯一，否则二进制日志无法启用</td></tr><tr><td><code>binlog_format</code></td><td>格式：ROW / STATEMENT / MIXED</td></tr><tr><td><code>sync_binlog</code></td><td>控制二进制日志同步到磁盘的频率。1=每次事务提交都同步，最安全</td></tr><tr><td><code>max_binlog_size</code></td><td>单个二进制日志文件大小上限（默认为1G）</td></tr><tr><td><code>binlog_expire_logs_seconds</code> (8.0+)</td><td>二进制日志自动清除的时间（秒），替代旧版 <code>expire_logs_days</code></td></tr><tr><td><code>binlog_row_image</code></td><td>行格式下的记录细节：full / minimal / noblob</td></tr></tbody></table><h3 id="常用操作" tabindex="-1">常用操作 <a class="header-anchor" href="#常用操作" aria-label="Permalink to &quot;常用操作&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 查看二进制日志列表</span></span>
<span class="line"><span class="__shiki_140thh">SHOW </span><span class="__shiki_1itgoe">BINARY</span><span class="__shiki_140thh"> LOGS;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 查看当前正在写入的二进制日志</span></span>
<span class="line"><span class="__shiki_140thh">SHOW </span><span class="__shiki_1itgoe">MASTER</span><span class="__shiki_1itgoe"> STATUS</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 查看日志事件</span></span>
<span class="line"><span class="__shiki_140thh">SHOW BINLOG EVENTS </span><span class="__shiki_1itgoe">IN</span><span class="__shiki_mdbnqw"> &#39;binlog.000003&#39;</span><span class="__shiki_1itgoe"> LIMIT</span><span class="__shiki_dzsirb"> 10</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 清除指定日志之前的所有文件</span></span>
<span class="line"><span class="__shiki_140thh">PURGE </span><span class="__shiki_1itgoe">BINARY</span><span class="__shiki_140thh"> LOGS </span><span class="__shiki_1itgoe">TO</span><span class="__shiki_mdbnqw"> &#39;binlog.000010&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 根据时间清除</span></span>
<span class="line"><span class="__shiki_140thh">PURGE </span><span class="__shiki_1itgoe">BINARY</span><span class="__shiki_140thh"> LOGS </span><span class="__shiki_1itgoe">BEFORE</span><span class="__shiki_mdbnqw"> &#39;2026-06-01 00:00:00&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 自动清除策略（8.0）</span></span>
<span class="line"><span class="__shiki_1itgoe">SET</span><span class="__shiki_1itgoe"> GLOBAL</span><span class="__shiki_140thh"> binlog_expire_logs_seconds </span><span class="__shiki_1itgoe">=</span><span class="__shiki_dzsirb"> 604800</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- 7天</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 重置（删除所有二进制日志并重新开始）</span></span>
<span class="line"><span class="__shiki_1itgoe">RESET</span><span class="__shiki_1itgoe"> MASTER</span><span class="__shiki_140thh">;  </span><span class="__shiki_21nrsd">-- 操作极其危险，仅测试环境</span></span></code></pre></div><h3 id="mysqlbinlog-工具" tabindex="-1">mysqlbinlog 工具 <a class="header-anchor" href="#mysqlbinlog-工具" aria-label="Permalink to &quot;mysqlbinlog 工具&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 解码 ROW 格式日志需要加 -v</span></span>
<span class="line"><span class="__shiki_1t8gfj">mysqlbinlog</span><span class="__shiki_dzsirb"> -v</span><span class="__shiki_dzsirb"> --base64-output=DECODE-ROWS</span><span class="__shiki_mdbnqw"> binlog.000003</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 按时间范围导出</span></span>
<span class="line"><span class="__shiki_1t8gfj">mysqlbinlog</span><span class="__shiki_dzsirb"> --start-datetime=</span><span class="__shiki_mdbnqw">&quot;2026-07-01 10:00:00&quot;</span><span class="__shiki_dzsirb"> \\</span></span>
<span class="line"><span class="__shiki_dzsirb">            --stop-datetime=</span><span class="__shiki_mdbnqw">&quot;2026-07-01 11:00:00&quot;</span><span class="__shiki_mdbnqw"> binlog.000003</span><span class="__shiki_1itgoe"> &gt;</span><span class="__shiki_mdbnqw"> restore.sql</span></span></code></pre></div><h3 id="binlog-与-redo-log-的对比-详见后续章节" tabindex="-1">Binlog 与 Redo Log 的对比 (详见后续章节) <a class="header-anchor" href="#binlog-与-redo-log-的对比-详见后续章节" aria-label="Permalink to &quot;Binlog 与 Redo Log 的对比 (详见后续章节)&quot;">​</a></h3><ul><li><strong>层次</strong>：Binlog 是 Server 层逻辑日志；Redo Log 是 InnoDB 层物理日志。</li><li><strong>内容</strong>：Binlog 记录“怎么修改的”；Redo Log 记录“在哪个表空间、哪个页的偏移量处修改了什么”。</li><li><strong>用途</strong>：Binlog 负责复制和 PITR；Redo Log 负责崩溃恢复，保证已提交事务的持久性。</li></ul><h3 id="两阶段提交-2pc" tabindex="-1">两阶段提交 (2PC) <a class="header-anchor" href="#两阶段提交-2pc" aria-label="Permalink to &quot;两阶段提交 (2PC)&quot;">​</a></h3><p>为了保证 Binlog 和 Redo Log 的一致性，InnoDB 采用内部 XA 事务：</p><ol><li><strong>Prepare 阶段</strong>：写入 Redo Log 并标记为 prepare 状态。</li><li><strong>写 Binlog</strong>：提交事务时写入 Binlog。</li><li><strong>Commit 阶段</strong>：将 Redo Log 中的对应事务标记为 commit 状态。<br> 如果在第二步之后、第三步之前崩溃，恢复时若发现 Binlog 中有该事务，则自动将 Redo Log 提交，从而保证主从一致。</li></ol><hr><h2 id="_6-中继日志-relay-log" tabindex="-1">6. 中继日志 (Relay Log) <a class="header-anchor" href="#_6-中继日志-relay-log" aria-label="Permalink to &quot;6. 中继日志 (Relay Log)&quot;">​</a></h2><h3 id="作用-4" tabindex="-1">作用 <a class="header-anchor" href="#作用-4" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>中继日志是<strong>从库（Replica/Slave）</strong> 上的日志。从库 I/O 线程接收主库的二进制日志事件并写入中继日志，SQL 线程再读取中继日志执行，实现复制。</p><h3 id="配置参数-4" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数-4" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>relay_log</code></td><td>中继日志文件基础名</td></tr><tr><td><code>relay_log_index</code></td><td>中继日志索引文件名</td></tr><tr><td><code>relay_log_purge</code></td><td>SQL 线程执行完成后是否自动删除中继日志（默认 ON）</td></tr><tr><td><code>max_relay_log_size</code></td><td>单个中继日志文件大小上限</td></tr><tr><td><code>relay_log_recovery</code> (8.0 默认开启)</td><td>从库崩溃后，根据存储的信息丢弃未完成的事务，保证数据一致</td></tr><tr><td><code>relay_log_info_repository</code></td><td>存放复制信息的方式：TABLE（推荐，默认）或 FILE</td></tr><tr><td><code>sync_relay_log</code></td><td>中继日志同步频率，默认 10000 表示每 10000 个事务同步一次</td></tr></tbody></table><h3 id="查看与管理-1" tabindex="-1">查看与管理 <a class="header-anchor" href="#查看与管理-1" aria-label="Permalink to &quot;查看与管理&quot;">​</a></h3><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 显示从库状态，包含中继日志信息</span></span>
<span class="line"><span class="__shiki_140thh">SHOW SLAVE </span><span class="__shiki_1itgoe">STATUS</span><span class="__shiki_140thh">\\G</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 或（8.0.22+ 新语法）</span></span>
<span class="line"><span class="__shiki_140thh">SHOW </span><span class="__shiki_1itgoe">REPLICA</span><span class="__shiki_1itgoe"> STATUS</span><span class="__shiki_140thh">\\G</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd">-- 查看中继日志事件</span></span>
<span class="line"><span class="__shiki_140thh">SHOW RELAYLOG EVENTS </span><span class="__shiki_1itgoe">IN</span><span class="__shiki_mdbnqw"> &#39;relay-log.000010&#39;</span><span class="__shiki_1itgoe"> LIMIT</span><span class="__shiki_dzsirb"> 5</span><span class="__shiki_140thh">;</span></span></code></pre></div><h3 id="自动清理" tabindex="-1">自动清理 <a class="header-anchor" href="#自动清理" aria-label="Permalink to &quot;自动清理&quot;">​</a></h3><p><code>relay_log_purge=ON</code> 时，SQL 线程执行完一个中继日志文件的所有事件后会自动将其删除，一般无需人工干预。如果遇到磁盘空间问题，可检查是否有未处理完成的日志积压。</p><hr><h2 id="_7-innodb-重做日志-redo-log" tabindex="-1">7. InnoDB 重做日志 (Redo Log) <a class="header-anchor" href="#_7-innodb-重做日志-redo-log" aria-label="Permalink to &quot;7. InnoDB 重做日志 (Redo Log)&quot;">​</a></h2><h3 id="作用-5" tabindex="-1">作用 <a class="header-anchor" href="#作用-5" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>Redo Log 是 InnoDB 存储引擎特有的物理日志，记录了对数据页的修改。核心目标是<strong>保证事务的持久性（Durability）</strong>，实现崩溃恢复（Crash Recovery）。</p><h3 id="工作原理-wal" tabindex="-1">工作原理 (WAL) <a class="header-anchor" href="#工作原理-wal" aria-label="Permalink to &quot;工作原理 (WAL)&quot;">​</a></h3><p>采用 <strong>Write-Ahead Logging（预写式日志）</strong> 策略：修改数据页前先将 Redo Log 写入磁盘。即使数据页本身还未刷新到磁盘，事务提交后数据仍不会丢失。崩溃恢复时，从上次检查点 (Checkpoint) 开始重放 Redo Log，将数据页恢复到崩溃前的状态。</p><h3 id="配置参数-5" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数-5" aria-label="Permalink to &quot;配置参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>innodb_log_file_size</code></td><td>每个 Redo Log 文件的大小（默认 48MB，建议 1GB 起）</td></tr><tr><td><code>innodb_log_files_in_group</code></td><td>Redo Log 文件组的文件数量（默认 2）</td></tr><tr><td><code>innodb_log_group_home_dir</code></td><td>Redo Log 存放目录，默认数据目录</td></tr><tr><td><code>innodb_flush_log_at_trx_commit</code></td><td><strong>最关键</strong>的持久性与性能参数（见下表）</td></tr></tbody></table><h3 id="innodb-flush-log-at-trx-commit-详解" tabindex="-1">innodb_flush_log_at_trx_commit 详解 <a class="header-anchor" href="#innodb-flush-log-at-trx-commit-详解" aria-label="Permalink to &quot;innodb_flush_log_at_trx_commit 详解&quot;">​</a></h3><table tabindex="0"><thead><tr><th>值</th><th>行为</th><th>特点</th></tr></thead><tbody><tr><td>1 (默认)</td><td>每次事务提交时将 Redo Log 写入并刷盘</td><td>完全持久化，不会丢事务，但性能开销最大</td></tr><tr><td>2</td><td>每次事务提交时写入 OS 缓存，每秒刷盘</td><td>OS 崩溃可能丢失 1 秒内事务，性能较好</td></tr><tr><td>0</td><td>每秒钟将 Redo Log 写入 OS 缓存并刷盘</td><td>性能最好，但 MySQL 崩溃会丢失 1 秒数据</td></tr></tbody></table><blockquote><p>⚠️ <strong>数据安全建议</strong>：核心业务系统必须设置 <code>innodb_flush_log_at_trx_commit=1</code> 并配合 <code>sync_binlog=1</code> 以保证 ACID 中的 D（持久性）。</p></blockquote><h3 id="redo-log-文件大小设置" tabindex="-1">Redo Log 文件大小设置 <a class="header-anchor" href="#redo-log-文件大小设置" aria-label="Permalink to &quot;Redo Log 文件大小设置&quot;">​</a></h3><ul><li>总大小 = <code>innodb_log_file_size</code> × <code>innodb_log_files_in_group</code>。</li><li>太小的日志会导致频繁检查点，影响写入性能；太大则崩溃恢复时间长。</li><li>修改文件大小需要先关闭 MySQL，移动旧日志文件，再重启（8.0 支持在线调整 <code>innodb_log_file_size</code>，通过 <code>innodb_log_file_size</code> 变量需重启生效？实际上 8.0.30 之前需要重启，之后支持在线调整 <code>innodb_redo_log_capacity</code> 新参数，但传统参数仍需重启）。</li></ul><hr><h2 id="_8-innodb-撤销日志-undo-log" tabindex="-1">8. InnoDB 撤销日志 (Undo Log) <a class="header-anchor" href="#_8-innodb-撤销日志-undo-log" aria-label="Permalink to &quot;8. InnoDB 撤销日志 (Undo Log)&quot;">​</a></h2><h3 id="作用-6" tabindex="-1">作用 <a class="header-anchor" href="#作用-6" aria-label="Permalink to &quot;作用&quot;">​</a></h3><p>Undo Log 记录事务修改前的数据版本，主要提供：</p><ul><li><strong>事务回滚</strong>：将数据恢复到修改前的状态。</li><li><strong>MVCC（多版本并发控制）</strong>：快照读时构造历史版本，实现非锁定一致性读。</li></ul><h3 id="存储管理" tabindex="-1">存储管理 <a class="header-anchor" href="#存储管理" aria-label="Permalink to &quot;存储管理&quot;">​</a></h3><ul><li>默认存放在共享表空间 <code>ibdata1</code> 中，但官方强烈建议使用<strong>独立的 Undo 表空间</strong>（5.6 引入，8.0 完全独立管理）。</li><li>8.0 的 Undo 表空间可通过 DDL 管理：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_140thh"> UNDO TABLESPACE undo_002 </span><span class="__shiki_1itgoe">ADD</span><span class="__shiki_140thh"> DATAFILE </span><span class="__shiki_mdbnqw">&#39;undo_002.ibu&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"><span class="__shiki_1itgoe">ALTER</span><span class="__shiki_140thh"> UNDO TABLESPACE undo_002 </span><span class="__shiki_1itgoe">SET</span><span class="__shiki_140thh"> INACTIVE; </span><span class="__shiki_21nrsd">-- 标记为不活动后删除</span></span>
<span class="line"><span class="__shiki_1itgoe">DROP</span><span class="__shiki_140thh"> UNDO TABLESPACE undo_002;</span></span></code></pre></div></li></ul><h3 id="相关参数" tabindex="-1">相关参数 <a class="header-anchor" href="#相关参数" aria-label="Permalink to &quot;相关参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>innodb_undo_directory</code></td><td>Undo 表空间的目录，默认数据目录</td></tr><tr><td><code>innodb_max_undo_log_size</code></td><td>Undo 表空间最大大小（默认 1GB），超过会标记为可截断</td></tr><tr><td><code>innodb_undo_log_truncate</code></td><td>是否启用 undo 表空间自动截断回收（默认 ON）</td></tr><tr><td><code>innodb_purge_threads</code></td><td>后台清理线程数</td></tr><tr><td><code>innodb_undo_tablespaces</code> (5.7)</td><td>已弃用，8.0 由 DDL 管理</td></tr></tbody></table><h3 id="长事务与-undo-log" tabindex="-1">长事务与 Undo Log <a class="header-anchor" href="#长事务与-undo-log" aria-label="Permalink to &quot;长事务与 Undo Log&quot;">​</a></h3><p>长时间未提交的事务会导致 Undo Log 无法回收，可能引起：</p><ul><li><strong>表空间膨胀</strong>：Undo 表空间不断增长。</li><li><strong>慢查询</strong>：历史版本链过长，MVCC 查询变慢。</li><li><strong>监控方式</strong>：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 查看活跃事务和运行时间</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> *</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_dzsirb"> information_schema</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">innodb_trx</span><span class="__shiki_1itgoe"> ORDER BY</span><span class="__shiki_140thh"> trx_started;</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 查看 undo 表空间大小</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_140thh"> TABLESPACE_NAME, FILE_NAME, FILE_SIZE</span><span class="__shiki_1itgoe">/</span><span class="__shiki_dzsirb">1024</span><span class="__shiki_1itgoe">/</span><span class="__shiki_dzsirb">1024</span><span class="__shiki_1itgoe"> AS</span><span class="__shiki_140thh"> MB</span></span>
<span class="line"><span class="__shiki_1itgoe">FROM</span><span class="__shiki_dzsirb"> information_schema</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">FILES</span><span class="__shiki_1itgoe"> WHERE</span><span class="__shiki_140thh"> FILE_TYPE </span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw"> &#39;UNDO LOG&#39;</span><span class="__shiki_140thh">;</span></span></code></pre></div></li></ul><hr><h2 id="_9-其他日志简介" tabindex="-1">9. 其他日志简介 <a class="header-anchor" href="#_9-其他日志简介" aria-label="Permalink to &quot;9. 其他日志简介&quot;">​</a></h2><h3 id="ddl-日志-innodb-ddl-log" tabindex="-1">DDL 日志 (InnoDB DDL Log) <a class="header-anchor" href="#ddl-日志-innodb-ddl-log" aria-label="Permalink to &quot;DDL 日志 (InnoDB DDL Log)&quot;">​</a></h3><ul><li>5.7 开始，InnoDB 在 DDL 操作过程中会将进度写入 <code>mysql.innodb_ddl_log</code> 表，用于崩溃恢复时继续或回滚 DDL。</li><li>完全由系统管理，DBA 通常无需干预。</li></ul><h3 id="审计日志-audit-log" tabindex="-1">审计日志 (Audit Log) <a class="header-anchor" href="#审计日志-audit-log" aria-label="Permalink to &quot;审计日志 (Audit Log)&quot;">​</a></h3><ul><li>不属于 MySQL 默认组件，通常使用插件（如 MySQL Enterprise Audit、Percona Audit Plugin、MariaDB Audit Plugin）。</li><li>可以记录用户连接、查询类型、操作对象等，用于安全审计。</li><li>相比通用查询日志，性能影响更小且可筛选。</li></ul><hr><h2 id="_10-日志综合管理与最佳实践" tabindex="-1">10. 日志综合管理与最佳实践 <a class="header-anchor" href="#_10-日志综合管理与最佳实践" aria-label="Permalink to &quot;10. 日志综合管理与最佳实践&quot;">​</a></h2><h3 id="空间与性能平衡" tabindex="-1">空间与性能平衡 <a class="header-anchor" href="#空间与性能平衡" aria-label="Permalink to &quot;空间与性能平衡&quot;">​</a></h3><ul><li><strong>二进制日志</strong>：推荐 <code>binlog_format=ROW</code>，<code>sync_binlog=1</code>，<code>binlog_expire_logs_seconds=604800</code>（7天），并监控磁盘使用。</li><li><strong>Redo Log</strong>：总大小建议等于或略大于 <code>innodb_log_file_size×innodb_log_files_in_group</code> 让写入性能平稳，生产通常 2-4 GB。</li><li><strong>慢查询日志</strong>：开启，长期保留以便历史分析，配合日志分析工具。</li></ul><h3 id="日常监控与轮转" tabindex="-1">日常监控与轮转 <a class="header-anchor" href="#日常监控与轮转" aria-label="Permalink to &quot;日常监控与轮转&quot;">​</a></h3><ul><li>使用监控系统检查日志文件所在分区的磁盘使用率。</li><li>通用查询日志和慢查询日志可启用操作系统 <code>logrotate</code> 轮转，并配合 <code>FLUSH LOGS</code>。</li><li>二进制日志依赖 <code>binlog_expire_logs_seconds</code> 自动清理，不必使用轮转。</li><li>错误日志注意定期归档。</li></ul><h3 id="备份策略中的日志" tabindex="-1">备份策略中的日志 <a class="header-anchor" href="#备份策略中的日志" aria-label="Permalink to &quot;备份策略中的日志&quot;">​</a></h3><ul><li>全量备份（如 mysqldump 或 XtraBackup）+ 二进制日志实现 PITR。备份后应立即记录当前的 Binlog 位置或 GTID。</li><li>从库上通过 <code>relay_log_recovery=ON</code> 保障复制的容错性。</li></ul><h3 id="关键安全配置清单" tabindex="-1">关键安全配置清单 <a class="header-anchor" href="#关键安全配置清单" aria-label="Permalink to &quot;关键安全配置清单&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">[mysqld]</span></span>
<span class="line"><span class="__shiki_21nrsd"># 二进制日志</span></span>
<span class="line"><span class="__shiki_1itgoe">server_id</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">log_bin</span><span class="__shiki_140thh"> = /data/binlog/mysql-bin</span></span>
<span class="line"><span class="__shiki_1itgoe">binlog_format</span><span class="__shiki_140thh"> = ROW</span></span>
<span class="line"><span class="__shiki_1itgoe">sync_binlog</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">binlog_expire_logs_seconds</span><span class="__shiki_140thh"> = 604800</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># Redo 日志（InnoDB）</span></span>
<span class="line"><span class="__shiki_1itgoe">innodb_flush_log_at_trx_commit</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">innodb_log_file_size</span><span class="__shiki_140thh"> = 1G</span></span>
<span class="line"><span class="__shiki_1itgoe">innodb_log_files_in_group</span><span class="__shiki_140thh"> = 2</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 慢查询日志</span></span>
<span class="line"><span class="__shiki_1itgoe">slow_query_log</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"><span class="__shiki_1itgoe">long_query_time</span><span class="__shiki_140thh"> = 0.5</span></span>
<span class="line"><span class="__shiki_1itgoe">log_queries_not_using_indexes</span><span class="__shiki_140thh"> = 1</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_21nrsd"># 错误日志</span></span>
<span class="line"><span class="__shiki_1itgoe">log_error</span><span class="__shiki_140thh"> = /var/log/mysql/error.log</span></span>
<span class="line"><span class="__shiki_1itgoe">log_error_verbosity</span><span class="__shiki_140thh"> = 3</span></span></code></pre></div><h3 id="故障排查顺序" tabindex="-1">故障排查顺序 <a class="header-anchor" href="#故障排查顺序" aria-label="Permalink to &quot;故障排查顺序&quot;">​</a></h3><ol><li><strong>连接失败或服务启动不了</strong> → 错误日志</li><li><strong>数据库响应突然变慢</strong> → 慢查询日志 + <code>SHOW PROCESSLIST</code> + <code>innodb_trx</code></li><li><strong>磁盘空间报警</strong> → 检查 <code>binlog</code>、<code>relay log</code>、<code>undo</code> 表空间、错误日志</li><li><strong>主从延迟</strong> → 中继日志积压情况、<code>SHOW REPLICA STATUS</code></li><li><strong>数据误删</strong> → 二进制日志 + 备份进行时间点恢复</li></ol><hr><h2 id="_11-总结" tabindex="-1">11. 总结 <a class="header-anchor" href="#_11-总结" aria-label="Permalink to &quot;11. 总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日志类型</th><th>所属层次</th><th>主要作用</th><th>是否默认开启</th><th>生产建议</th></tr></thead><tbody><tr><td>错误日志</td><td>Server</td><td>记录启动、运行、错误信息</td><td>是</td><td>必须开启</td></tr><tr><td>通用查询日志</td><td>Server</td><td>记录所有 SQL (流水账)</td><td>否</td><td>临时调试，用完即关</td></tr><tr><td>慢查询日志</td><td>Server</td><td>记录超出阈值的 SQL，优化利器</td><td>否</td><td>建议开启</td></tr><tr><td>二进制日志</td><td>Server</td><td>复制与时间点恢复</td><td>否（需配置 server_id 和 log_bin）</td><td>必须开启</td></tr><tr><td>中继日志</td><td>Server (从库)</td><td>暂存主库传来的 Binlog 事件</td><td>复制开启时自动创建</td><td>使用默认配置即可</td></tr><tr><td>Redo Log</td><td>InnoDB</td><td>保证持久性，崩溃恢复</td><td>是（固定两个文件）</td><td>关注大小与刷盘策略</td></tr><tr><td>Undo Log</td><td>InnoDB</td><td>回滚与 MVCC</td><td>是（系统管理）</td><td>监控长事务，独立表空间</td></tr></tbody></table><p>深刻理解这些日志的设计与协同，是掌握 MySQL 高可用、高性能和数据安全的关键。建议结合实际环境，逐一配置并实践日志的分析与故障排查，才能将理论知识转化为真正的运维能力。</p>`,121)])])}const g=a(l,[["render",e]]);export{c as __pageData,g as default};
